import { isMatching, match, P } from '../src';
import { Equal, Expect } from '../src/types/helpers';

describe('Objects', () => {
  describe('symbols', () => {
    const symbolA = Symbol('symbol-a');
    const symbolB = Symbol('symbol-b');
    const symbolC = Symbol('symbol-c');
    type Input = { [symbolA]: { [symbolB]: 'foo' | 'bar' } };

    it('should work with symbols', () => {
      const fn1 = (obj: Input) => {
        if (isMatching({ [symbolA]: { [symbolB]: 'foo' } }, obj)) {
          const value = obj[symbolA][symbolB];
          type t = Expect<Equal<typeof value, 'foo'>>;
        } else {
          throw new Error('Expected obj to match the foo pattern!');
        }
      };

      const fn2 = (obj: Input) => {
        if (isMatching({ [symbolA]: { [symbolB]: 'bar' } }, obj)) {
          const value = obj[symbolA][symbolB];
          type t = Expect<Equal<typeof value, 'bar'>>;
          throw new Error('Expected obj to not match the bar pattern!');
        }
      };

      fn1({
        [symbolA]: { [symbolB]: 'foo' },
      });

      fn2({
        [symbolA]: { [symbolB]: 'foo' },
      });
    });

    it('narrowing inference should work', () => {
      const fn1 = (input: Input) => {
        return match(input)
          .with({ [symbolA]: P.select() }, (sel) => {
            type t = Expect<Equal<typeof sel, { [symbolB]: 'foo' | 'bar' }>>;
            return sel;
          })
          .exhaustive();
      };

      expect(fn1({ [symbolA]: { [symbolB]: 'bar' } })).toEqual({
        [symbolB]: 'bar',
      });

      const fn2 = (input: Input | { [symbolC]: string }) => {
        return match(input)
          .with({ [symbolA]: P.any }, (sel) => {
            type t = Expect<Equal<typeof sel, Input>>;
            return sel;
          })
          .with({ [symbolC]: P.select() }, (x) => x)
          .exhaustive();
      };

      expect(fn2({ [symbolC]: 'Hey' })).toEqual('Hey');
    });

    it('exhaustiveness checking should work', () => {
      const fn1 = (input: Input | { [symbolC]: string }) => {
        return match(input)
          .with({ [symbolA]: P.any }, (sel) => {
            type t = Expect<Equal<typeof sel, Input>>;
            return sel;
          })
          .with({ [symbolC]: P.any }, () => '2')
          .exhaustive();
      };

      const fn2 = (input: Input | { [symbolC]: string }) => {
        return (
          match(input)
            .with({ [symbolA]: P.any }, (sel) => {
              type t = Expect<Equal<typeof sel, Input>>;
              return sel;
            })
            // @ts-expect-error
            .exhaustive()
        );
      };
    });
  });
});

describe('Records ({})', () => {
  it('Should match records', () => {
    type Vector1 = { x: number };
    type Vector2 = { x: number; y: number };
    type Vector3 = {
      x: number;
      y: number;
      z: number;
    };
    type Vector = Vector1 | Vector2 | Vector3;

    const vector: Vector = { x: 1 };

    expect(
      match<Vector, string>(vector)
        .with({ x: 1, y: 1, z: 1 }, (x) => {
          type t = Expect<Equal<typeof x, { x: 1; y: 1; z: 1 }>>;
          return 'vector3';
        })
        .with({ x: 2, y: 1 }, (x) => {
          type t = Expect<
            Equal<typeof x, { x: 2; y: 1 } | { z: number; x: 2; y: 1 }>
          >;
          return 'vector2';
        })
        .with({ x: 1 }, (x) => {
          type t = Expect<
            Equal<
              typeof x,
              { x: 1 } | { x: 1; y: number } | { x: 1; y: number; z: number }
            >
          >;
          return 'vector1';
        })
        .otherwise(() => 'no match')
    ).toEqual('vector1');
  });
});

describe('P.object', () => {
  it('should match plain objects with isMatching', () => {
    expect(isMatching(P.object, {})).toBe(true);
    expect(isMatching(P.object, { a: 1 })).toBe(true);
    expect(isMatching(P.object, Object.create(null))).toBe(true);
    // non-objects should not match
    expect(isMatching(P.object, null)).toBe(false);
    expect(isMatching(P.object, undefined)).toBe(false);
    expect(isMatching(P.object, 'string')).toBe(false);
    expect(isMatching(P.object, 42)).toBe(false);
    expect(isMatching(P.object, true)).toBe(false);
  });

  it('should match arrays, Maps and Sets with isMatching', () => {
    expect(isMatching(P.object, [])).toBe(true);
    expect(isMatching(P.object, [1, 2])).toBe(true);
    expect(isMatching(P.object, new Map())).toBe(true);
    expect(isMatching(P.object, new Map([['a', 1]]))).toBe(true);
    expect(isMatching(P.object, new Set())).toBe(true);
    expect(isMatching(P.object, new Set([1]))).toBe(true);
  });

  it('should work with match().with()', () => {
    const fn = (input: unknown) =>
      match(input)
        .with(P.object, (value) => {
          type t = Expect<Equal<typeof value, object>>;
          return 'object';
        })
        .otherwise(() => 'not object');

    expect(fn({})).toBe('object');
    expect(fn({ a: 1 })).toBe('object');
    expect(fn([])).toBe('object');
    expect(fn(new Map())).toBe('object');
    expect(fn(new Set())).toBe('object');
    expect(fn(Object.create(null))).toBe('object');
    expect(fn(null)).toBe('not object');
    expect(fn(undefined)).toBe('not object');
    expect(fn('hello')).toBe('not object');
    expect(fn(42)).toBe('not object');
  });

  it('.optional() should work on P.object', () => {
    const pattern = { val: P.object.optional() };

    expect(isMatching(pattern, { val: {} })).toBe(true);
    expect(isMatching(pattern, { val: null })).toBe(false);
    expect(isMatching(pattern, {})).toBe(true); // undefined optionals match
    expect(isMatching(pattern, { val: [1] })).toBe(true);
  });

  it('.and() should work on P.object', () => {
    const pattern = P.object.and(P.when((val) => (val as object) !== null && 'a' in val));

    expect(isMatching(pattern, { a: 1 })).toBe(true);
    expect(isMatching(pattern, {})).toBe(false);
    expect(isMatching(pattern, [1])).toBe(false); // array doesn't have 'a' property-like key
  });

  it('.or() should work on P.object', () => {
    const pattern = P.object.or(P.string);

    expect(isMatching(pattern, {})).toBe(true);
    expect(isMatching(pattern, 'hello')).toBe(true);
    expect(isMatching(pattern, null)).toBe(false);
    expect(isMatching(pattern, 42)).toBe(false);
  });

  it('.select() should work on P.object', () => {
    const fn = (input: unknown) =>
      match(input)
        .with(P.select(), (value) => value)
        .otherwise(() => null);

    expect(fn({ x: 1 })).toEqual({ x: 1 });
    expect(fn([])).toEqual([]);
    expect(fn(new Map())).toEqual(new Map());
  });

  describe('P.object.empty', () => {
    it('should match plain empty objects with isMatching', () => {
      expect(isMatching(P.object.empty!, {})).toBe(true);
      expect(isMatching(P.object.empty!, Object.create(null))).toBe(true);
      // non-empty should not match
      expect(isMatching(P.object.empty, { a: 1 })).toBe(false);
      expect(isMatching(P.object.empty, { a: 1, b: 2 })).toBe(false);
    });

    it('should not match arrays, Maps or Sets', () => {
      expect(isMatching(P.object.empty as any, [])).toBe(false);
      expect(isMatching(P.object.empty as any, [1])).toBe(false);
      expect(isMatching(P.object.empty as any, new Map())).toBe(false);
      expect(isMatching(P.object.empty as any, new Map([['a', 1]]))).toBe(false);
      expect(isMatching(P.object.empty as any, new Set())).toBe(false);
    });

    it('should not match null or undefined', () => {
      expect(isMatching(P.object.empty as any, null)).toBe(false);
      expect(isMatching(P.object.empty as any, undefined)).toBe(false);
    });

    it('should work with match().with()', () => {
      const fn = (input: unknown) =>
        match(input)
          .with({ val: P.object.empty! }, ({ val }) => {
            type t = Expect<Equal<typeof val, object>>;
            return 'empty';
          })
          .otherwise(() => 'not empty');

      expect(fn({ val: {} })).toBe('empty');
      expect(fn({ val: Object.create(null) })).toBe('empty');
      expect(fn({ val: { a: 1 } })).toBe('not empty');
      expect(fn({ val: [] })).toBe('not empty');
      expect(fn({ val: new Map() })).toBe('not empty');
      expect(fn({ val: null })).toBe('not empty');
    });

    it('.optional() should work on P.object.empty', () => {
      const pattern = { val: (P.object.empty as any).optional() };

      expect(isMatching(pattern, { val: {} })).toBe(true);
      expect(isMatching(pattern, { val: null })).toBe(false);
      expect(isMatching(pattern, {})).toBe(true); // undefined matches optional
      expect(isMatching(pattern, { val: { a: 1 } })).toBe(false);
    });

    it('.and() should work on P.object.empty', () => {
      const pattern = (P.object.empty as any).and(P.when(() => true));

      expect(isMatching(pattern, {})).toBe(true);
      expect(isMatching(pattern, { a: 1 })).toBe(false);
      expect(isMatching(pattern, null)).toBe(false);
    });

    it('.or() should work on P.object.empty', () => {
      const pattern = (P.object.empty as any).or(P.string);

      expect(isMatching(pattern, {})).toBe(true);
      expect(isMatching(pattern, 'hello')).toBe(true);
      expect(isMatching(pattern, { a: 1 })).toBe(false);
      expect(isMatching(pattern, null)).toBe(false);
    });

    it('.select() should work on P.object.empty', () => {
      const fn = (input: unknown) =>
        match(input)
          .with({ val: (P.object.empty as any).select() }, (value) => value)
          .otherwise(() => null);

      expect(fn({ val: {} })).toEqual({});
      expect(fn({ val: Object.create(null) })).toEqual(Object.create(null));
    });
  });
});

